**Assumptions:**

* We have a table `users` with columns `id`, `email`, and `rate_limit_exceeded`.
* We have a table `requests` with columns `id`, `user_id`, `timestamp`, and `captcha_passed`.

**Updated SQL Code:**
```sql
CREATE TABLE IF NOT EXISTS rate_limits (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id),
  max_requests_per_minute INTEGER NOT NULL DEFAULT 5,
  last_request_timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (user_id)
);

CREATE TABLE IF NOT EXISTS captchas (
  id SERIAL PRIMARY KEY,
  request_id INTEGER NOT NULL REFERENCES requests(id),
  captcha_text TEXT NOT NULL,
  solution TEXT NOT NULL
);

-- Function to check if rate limit has been exceeded
CREATE OR REPLACE FUNCTION is_rate_limit_exceeded(user_id INTEGER) RETURNS BOOLEAN AS $$
DECLARE
  current_timestamp TIMESTAMP;
BEGIN
  SELECT INTO current_timestamp last_request_timestamp FROM rate_limits WHERE user_id = $1;
  IF (EXTRACT(EPOCH FROM CURRENT_TIMESTAMP - current_timestamp) < 60 AND 
     (SELECT COUNT(*) FROM requests WHERE user_id = $1 AND timestamp > current_timestamp) >= 5) THEN
    RETURN TRUE;
  ELSE
    RETURN FALSE;
  END IF;
END;
$$ LANGUAGE plpgsql;

-- Function to handle CAPTCHA verification
CREATE OR REPLACE FUNCTION verify_captcha(request_id INTEGER, solution TEXT) RETURNS BOOLEAN AS $$
DECLARE
  captcha_text TEXT;
BEGIN
  SELECT INTO captcha_text captcha_text FROM captchas WHERE request_id = $1;
  IF (captcha_text IS NOT NULL AND solution = captcha_text) THEN
    RETURN TRUE;
  ELSE
    RETURN FALSE;
  END IF;
END;
$$ LANGUAGE plpgsql;

