A file deletion system is a program that allows users to delete files from their computer or storage device. Here's a simplified example of how you might implement such a system in Python:
```python
import os

class FileDeletionSystem:
    def __init__(self, directory):
        self.directory = directory

    def list_files(self):
        return os.listdir(self.directory)

    def delete_file(self, filename):
        file_path = os.path.join(self.directory, filename)
        if os.path.exists(file_path):
            os.remove(file_path)
            print(f"File '{filename}' deleted successfully!")
        else:
            print(f"File '{filename}' not found!")

    def main(self):
        while True:
            print("File Deletion System")
            print("--------------------")
            print("1. List files")
            print("2. Delete file")
            print("3. Quit")

            choice = input("Enter your choice: ")

            if choice == "1":
                files = self.list_files()
                for file in files:
                    print(file)
            elif choice == "2":
                filename = input("Enter the file name to delete: ")
                self.delete_file(filename)
            elif choice == "3":
                break
            else:
                print("Invalid choice. Try again!")

if __name__ == "__main__":
    system = FileDeletionSystem("/path/to/directory")
    system.main()
